    name: str = Field(min_length=1, max_length=64, pattern=r"^[A-Za-z][A-Za-z0-9_./:-]{0,63}$", description="Joint, arm, camera, or frame name.")
    kind: CameraKind = Field(description="Camera stream kind. rgb is a colour image. depth is a depth image. bev is a stitched bird's-eye image.")
