    max_wz_rad_s: float = Field(ge=0, le=1, description="Hard cap on yaw rate in radians per second. Ceiling 1.0.")
    max_accel_x_mps2: float = Field(ge=0, le=0.5, description="Hard cap on forward acceleration in metres per second squared. Ceiling 0.5.")
    max_accel_y_mps2: float = Field(ge=0, le=0.5, description="Hard cap on lateral acceleration in metres per second squared. Ceiling 0.5.")
